40	    @Test
41	    public void testGlobalBean() throws Exception {
42	        context.getRegistry().bind("myBar", (Processor) ex -> ex.getMessage().setBody("Global " + ex.getMessage().getBody()));
43	
44	        context.addRoutes(new RouteBuilder() {
45	            @Override
46	            public void configure() {
47	                routeTemplate("myTemplate").templateParameter("foo").templateParameter("bar")
48	                        .from("direct:{{foo}}")
49	                        .to("bean:{{bar}}");
50	            }
51	        });
52	
53	        context.start();
54	
55	        TemplatedRouteBuilder.builder(context, "myTemplate")
56	                .parameter("foo", "one")
57	                .parameter("bar", "myBar")
58	                .routeId("myRoute")
59	                .add();
60	
61	        assertEquals(1, context.getRoutes().size());
62	
63	        Object out = template.requestBody("direct:one", "World");
64	        assertEquals("Global World", out);
65	
66	        // should be a global bean
67	        assertNotNull(context.getRegistry().lookupByName("myBar"));
68	
69	        context.stop();
70	    }
