72	    @Test
73	    public void testLocalBeanFoundByReifier() throws Exception {
74	        // Test that AbstractReifier can find a local bean (kamelet scenario)
75	        // Local bean is defined via templateBean, NOT in global registry
76	        context.addRoutes(new RouteBuilder() {
77	            @Override
78	            public void configure() {
79	                routeTemplate("myTemplate").templateParameter("foo").templateParameter("bar")
80	                        .templateBean("myLocalBean",
81	                                (Processor) ex -> ex.getMessage().setBody("LocalOnly " + ex.getMessage().getBody()))
82	                        .from("direct:{{foo}}")
83	                        .to("bean:{{bar}}");
84	            }
85	        });
86	
87	        context.start();
88	
89	        TemplatedRouteBuilder.builder(context, "myTemplate")
90	                .parameter("foo", "one")
91	                .parameter("bar", "myLocalBean")
92	                .routeId("myRoute")
93	                .add();
94	
95	        assertEquals(1, context.getRoutes().size());
96	
97	        // AbstractReifier should find the local bean and use it
98	        Object out = template.requestBody("direct:one", "World");
99	        assertEquals("LocalOnly World", out);
100	
101	        // Bean should NOT be in global registry (kamelet local beans are scoped to route template)
102	        assertNull(context.getRegistry().lookupByName("myLocalBean"));
103	
104	        context.stop();
105	    }
