107	    @Test
108	    public void testLocalBeanOverridesGlobalBean() throws Exception {
109	        // Test that local bean takes precedence when both local and global beans exist with same name
110	        // This ensures AbstractReifier checks local repository BEFORE global registry
111	
112	        // Register a global bean with the same name
113	        context.getRegistry().bind("myBar", (Processor) ex -> ex.getMessage().setBody("Global " + ex.getMessage().getBody()));
114	
115	        context.addRoutes(new RouteBuilder() {
116	            @Override
117	            public void configure() {
118	                routeTemplate("myTemplate").templateParameter("foo").templateParameter("bar")
119	                        .from("direct:{{foo}}")
120	                        .to("bean:{{bar}}");
121	            }
122	        });
123	
124	        context.start();
125	
126	        // Create route with local bean that has the same name as global bean
127	        TemplatedRouteBuilder.builder(context, "myTemplate")
128	                .parameter("foo", "one")
129	                .parameter("bar", "myBar")
130	                .bean("myBar", (Processor) ex -> ex.getMessage().setBody("Local " + ex.getMessage().getBody()))
131	                .routeId("myRoute")
132	                .add();
133	
134	        assertEquals(1, context.getRoutes().size());
135	
136	        // The local bean should take precedence over the global bean
137	        Object out = template.requestBody("direct:one", "World");
138	        assertEquals("Local World", out);
139	
140	        // Global bean should still exist in registry
141	        assertNotNull(context.getRegistry().lookupByName("myBar"));
142	
143	        context.stop();
144	    }
