            }
        });

        context.start();

        TemplatedRouteBuilder.builder(context, "myTemplate")
                .parameter("foo", "one")
                .parameter("scheme", "counter")
                .routeId("myRoute")
                .add();

        assertEquals(1, context.getRoutes().size());

        Object out = template.requestBody("direct:one", "World");
        assertEquals(0, out);
        out = template.requestBody("direct:one", "World");
        assertEquals(1, out);

        context.stop();
    }

}

