423	    /**
424	     * Creates a copy of this template as a {@link RouteDefinition} which can be used to add as a new route.
425	     */
426	    public RouteDefinition asRouteDefinition() {
427	        RouteDefinition copy = new RouteDefinition();
428	
429	        // must set these first in this order
430	        copy.setErrorHandlerRef(route.getErrorHandlerRef());
431	        if (route.isErrorHandlerFactorySet()) {
432	            // only set factory if not already set
433	            copy.setErrorHandlerFactory(route.getErrorHandlerFactory());
434	        }
435	        copy.setErrorHandler(route.getErrorHandler());
436	
437	        // ensure the copy has unique node prefix to avoid duplicate id clash
438	        // when creating multiple routes from the same template
439	        copy.setNodePrefixId(route.getNodePrefixId());
440	        String npi = copy.getNodePrefixId();
441	        if (npi == null) {
442	            npi = "route";
443	        }
444	        npi = npi + "-" + incNodePrefixId();
445	        copy.setNodePrefixId(npi);
446	
447	        // and then copy over the rest
448	        // (do not copy id as it is used for route template id)
449	        copy.setAutoStartup(route.getAutoStartup());
450	        copy.setDelayer(route.getDelayer());
451	        copy.setGroup(route.getGroup());
452	        // make a defensive copy of the input as input can be adviced during testing or other changes
453	        copy.setInput(route.getInput().copy());
454	        copy.setInputType(route.getInputType());
455	        copy.setLogMask(route.getLogMask());
456	        copy.setMessageHistory(route.getMessageHistory());
457	        copy.setOutputType(route.getOutputType());
458	        copy.setOutputs(ProcessorDefinitionHelper.deepCopyDefinitions(route.getOutputs()));
459	        copy.setRoutePolicies(shallowCopy(route.getRoutePolicies()));
460	        copy.setRoutePolicyRef(route.getRoutePolicyRef());
461	        copy.setRouteProperties(shallowCopy(route.getRouteProperties()));
462	        copy.setShutdownRoute(route.getShutdownRoute());
463	        copy.setShutdownRunningTask(route.getShutdownRunningTask());
464	        copy.setStartupOrder(route.getStartupOrder());
465	        copy.setStreamCache(route.getStreamCache());
466	        copy.setTemplate(true);
467	        copy.setTrace(route.getTrace());
468	        if (route.getDescription() != null) {
469	            copy.setDescription(route.getDescription());
470	        } else {
471	            copy.setDescription(getDescription());
472	        }
473	        if (route.getNote() != null) {
474	            copy.setNote(route.getNote());
475	        } else {
476	            copy.setNote(getNote());
477	        }
478	        copy.setPrecondition(route.getPrecondition());
479	        copy.setRouteConfigurationId(route.getRouteConfigurationId());
480	        copy.setTemplateParameters(shallowCopy(route.getTemplateParameters()));
481	        return copy;
482	    }
483	
484	    private <T> List<T> shallowCopy(List<T> list) {
485	        return (list != null) ? new ArrayList<>(list) : null;
486	    }
487	
488	    private <K, V> Map<K, V> shallowCopy(Map<K, V> map) {
489	        return (map != null) ? new HashMap<>(map) : null;
490	    }
491	
492	    private int incNodePrefixId() {
493	        return COUNTER.incrementAndGet();
494	    }
