512	         *
513	         * @param  in         the {@link RouteTemplateDefinition} to convert
514	         * @param  parameters parameters that are given to the {@link Model#addRouteFromTemplate(String, String, Map)}.
515	         *                    Implementors are free to add or remove additional parameter.
516	         * @return            the generated {@link RouteDefinition}
517	         */
518	        RouteDefinition apply(RouteTemplateDefinition in, Map<String, Object> parameters) throws Exception;
519	    }
